    <script>
        // Coin rendering system
        class CoinRenderer {
            constructor(canvas, options = {}) {
                this.canvas = canvas;
                this.ctx = canvas.getContext('2d');
                this.options = {
                    metallic: 'gold',
                    frontText: 'WASTEDTOKEN',
                    backText: '10,000 TOKENS',
                    ...options
                };
                this.time = 0;
                this.animationId = null;
                this.paused = false;
            }

            setTime(t) {
                this.time = t;
                this.render();
            }

            pause() {
                this.paused = true;
                if (this.animationId) {
                    cancelAnimationFrame(this.animationId);
                }
            }

            resume() {
                this.paused = false;
                this.animate();
            }

            animate() {
                if (!this.paused) {
                    this.time = (this.time + 0.006) % 1;
                    this.render();
                    this.animationId = requestAnimationFrame(() => this.animate());
                }
            }

            render() {
                const w = this.canvas.width;
                const h = this.canvas.height;

                // Clear canvas
                this.ctx.fillStyle = 'rgba(15, 15, 15, 0.9)';
                this.ctx.fillRect(0, 0, w, h);

                // Apply radial gradient background
                const bgGrad = this.ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w);
                bgGrad.addColorStop(0, '#2a2a3a');
                bgGrad.addColorStop(1, '#0f0f0f');
                this.ctx.fillStyle = bgGrad;
                this.ctx.fillRect(0, 0, w, h);

                // Transform to center
                this.ctx.save();
                this.ctx.translate(w / 2, h / 2);

                // Calculate coin animation (rotation + flip)
                const rotationY = this.time * Math.PI * 2; // Full rotation
                const flip = Math.sin(this.time * Math.PI * 2) * 0.5 + 0.5; // Flip between 0-1
                const scaleY = Math.abs(Math.cos(this.time * Math.PI * 2)); // Perspective scale

                // Draw coin with 3D perspective
                this.drawCoin3D(rotationY, scaleY, flip);

                this.ctx.restore();
            }

            drawCoin3D(rotationY, scaleY, flip) {
                const radius = 150;
                const ctx = this.ctx;

                // Determine which face is visible
                const isFront = flip < 0.5;

                // Draw coin body with perspective
                ctx.save();
                ctx.scale(1, scaleY);

                // Draw coin base circle
                const grad = ctx.createRadialGradient(-30, -30, 0, 0, 0, radius * 1.2);

                if (this.options.metallic === 'gold') {
                    grad.addColorStop(0, '#f4d03f');
                    grad.addColorStop(0.3, '#d4af37');
                    grad.addColorStop(0.7, '#b8860b');
                    grad.addColorStop(1, '#8b6914');
                } else if (this.options.metallic === 'silver') {
                    grad.addColorStop(0, '#e8e8e8');
                    grad.addColorStop(0.3, '#c0c0c0');
                    grad.addColorStop(0.7, '#a8a8a8');
                    grad.addColorStop(1, '#808080');
                } else if (this.options.metallic === 'bronze') {
                    grad.addColorStop(0, '#cd7f32');
                    grad.addColorStop(0.3, '#b87333');
                    grad.addColorStop(0.7, '#8b4513');
                    grad.addColorStop(1, '#5c3d1f');
                } else if (this.options.metallic === 'black') {
                    grad.addColorStop(0, '#2a2a2a');
                    grad.addColorStop(0.3, '#1a1a1a');
                    grad.addColorStop(0.7, '#0a0a0a');
                    grad.addColorStop(1, '#000000');
                }

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.arc(0, 0, radius, 0, Math.PI * 2);
                ctx.fill();

                // Draw reeded edge
                ctx.strokeStyle = 'rgba(0, 0, 0, 0.4)';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.arc(0, 0, radius, 0, Math.PI * 2);
                ctx.stroke();

                // Draw reeds (ridges on edge)
                ctx.strokeStyle = 'rgba(0, 0, 0, 0.3)';
                ctx.lineWidth = 1;
                for (let i = 0; i < 24; i++) {
                    const angle = (i / 24) * Math.PI * 2;
                    const x1 = Math.cos(angle) * (radius - 5);
                    const y1 = Math.sin(angle) * (radius - 5);
                    const x2 = Math.cos(angle) * (radius + 2);
                    const y2 = Math.sin(angle) * (radius + 2);
                    ctx.beginPath();
                    ctx.moveTo(x1, y1);
                    ctx.lineTo(x2, y2);
                    ctx.stroke();
                }

                // Draw embossed content (front or back)
                if (isFront) {
                    this.drawFront(radius);
                } else {
                    this.drawBack(radius);
                }

                // Draw specular highlight (moving with rotation)
                const highlightAngle = rotationY;
                const highlightX = Math.cos(highlightAngle) * radius * 0.4;
                const highlightY = Math.sin(highlightAngle) * radius * 0.3;

                const highlightGrad = ctx.createRadialGradient(
                    highlightX, highlightY, 0,
                    highlightX, highlightY, radius * 0.6
                );
                highlightGrad.addColorStop(0, 'rgba(255, 255, 255, 0.6)');
                highlightGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.2)');
                highlightGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');

                ctx.fillStyle = highlightGrad;
                ctx.beginPath();
                ctx.arc(highlightX, highlightY, radius * 0.8, 0, Math.PI * 2);
                ctx.fill();

                // Draw shadow on opposite side
                const shadowAngle = highlightAngle + Math.PI;
                const shadowX = Math.cos(shadowAngle) * radius * 0.3;
                const shadowY = Math.sin(shadowAngle) * radius * 0.2;

                const shadowGrad = ctx.createRadialGradient(
                    shadowX, shadowY, 0,
                    shadowX, shadowY, radius * 0.5
                );
                shadowGrad.addColorStop(0, 'rgba(0, 0, 0, 0.2)');
                shadowGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');

                ctx.fillStyle = shadowGrad;
                ctx.beginPath();
                ctx.arc(shadowX, shadowY, radius * 0.7, 0, Math.PI * 2);
                ctx.fill();

                ctx.restore();
            }

            drawFront(radius) {
                const ctx = this.ctx;
                ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
                ctx.font = 'bold 18px serif';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';

                // Draw emblem-like circle
                ctx.strokeStyle = 'rgba(0, 0, 0, 0.5)';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.arc(0, -40, 35, 0, Math.PI * 2);
                ctx.stroke();

                // Draw inner cross (crown symbol)
                ctx.strokeStyle = 'rgba(0, 0, 0, 0.5)';
                ctx.lineWidth = 1.5;
                ctx.beginPath();
                ctx.moveTo(0, -70);
                ctx.lineTo(0, -10);
                ctx.stroke();
                ctx.beginPath();
                ctx.moveTo(-20, -40);
                ctx.lineTo(20, -40);
                ctx.stroke();

                // Text
                ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
                ctx.font = 'bold 14px sans-serif';
                ctx.fillText(this.options.frontText, 0, 30);
                ctx.font = 'bold 10px sans-serif';
                ctx.fillText('EST. 2025', 0, 55);
            }

            drawBack(radius) {
                const ctx = this.ctx;
                ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
                ctx.font = 'bold 16px serif';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';

                // Draw denomination circle
                ctx.strokeStyle = 'rgba(0, 0, 0, 0.5)';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.arc(0, 0, 60, 0, Math.PI * 2);
                ctx.stroke();

                // Draw inner circle
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.arc(0, 0, 50, 0, Math.PI * 2);
                ctx.stroke();

                // Text
                ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
                ctx.font = 'bold 16px sans-serif';
                ctx.fillText(this.options.backText, 0, 0);
                ctx.font = 'bold 12px sans-serif';
                ctx.fillText('COLLECTIBLE', 0, 35);
            }
        }

        // Initialize hero coin
        const heroCanvas = document.getElementById('coin-hero');
        heroCanvas.width = 500;
        heroCanvas.height = 500;

        const heroRenderer = new CoinRenderer(heroCanvas, {
            metallic: 'gold',
            frontText: 'WASTEDTOKEN',
            backText: '10,000 TOKENS'
        });

        // Expose API for grading
        window.demo = {
            canvas: heroCanvas,
            setTime(t) {
                heroRenderer.setTime(t);
            },
            pause() {
                heroRenderer.pause();
            }
        };

        // Start hero animation
        heroRenderer.animate();

        // Initialize edition coins
        const editions = [
            { element: document.querySelector('[data-edition="bronze"]'), metallic: 'bronze', backText: '5,000 TOKENS' },
            { element: document.querySelector('[data-edition="silver"]'), metallic: 'silver', backText: '7,500 TOKENS' },
            { element: document.querySelector('[data-edition="gold"]'), metallic: 'gold', backText: '10,000 TOKENS' },
            { element: document.querySelector('[data-edition="black"]'), metallic: 'black', backText: '15,000 TOKENS' }
        ];

        editions.forEach(edition => {
            const canvas = edition.element.querySelector('.edition-canvas');
            canvas.width = 300;
            canvas.height = 300;

            const renderer = new CoinRenderer(canvas, {
                metallic: edition.metallic,
                frontText: 'WASTEDTOKEN',
                backText: edition.backText
            });

            // Set a static time for edition coins
            renderer.setTime(0.25);
        });

        // Button interactions
        document.querySelectorAll('.buy').forEach(button => {
            button.addEventListener('click', function(e) {
                if (!this.disabled) {
                    alert(`Added ${this.closest('.edition').querySelector('.edition-name').textContent} to cart!`);
                }
            });
        });

        // CTA button
        document.querySelector('.cta-button').addEventListener('click', function() {
            document.getElementById('collections').scrollIntoView({ behavior: 'smooth' });
        });
    </script>
